Here are the unit tests for the `is_palindrome` function using Python's built-in `unittest` framework:

```python
import unittest

def is_palindrome(s):
    return s == s[::-1]

class TestIsPalindrome(unittest.TestCase):
    def test_simple_palindrome(self):
        self.assertTrue(is_palindrome("racecar"))

    def test_simple_non_palindrome(self):
        self.assertFalse(is_palindrome("hello"))

    def test_single_character(self):
        self.assertTrue(is_palindrome("a"))

    def test_empty_string(self):
        self.assertTrue(is_palindrome(""))

    def test_palindrome_with_spaces(self):
        # Note: This test checks exact string equality including spaces.
        # "a b a" is a palindrome because it reads the same forwards and backwards.
        self.assertTrue(is_palindrome("a b a"))

    def test_non_palindrome_with_spaces(self):
        self.assertFalse(is_palindrome("a b c"))

    def test_case_sensitive(self):
        # "Racecar" is not equal to "racecaR" reversed if case matters.
        # "Racecar" reversed is "racecaR".
        self.assertFalse(is_palindrome("Racecar"))

    def test_numeric_string(self):
        self.assertTrue(is_palindrome("12321"))
        self.assertFalse(is_palindrome("12345"))

if __name__ == '__main__':
    unittest.main()
